-- ============================================================
-- Butir DUMMY untuk SELURUH topik dan SELURUH level Bloom
--
-- SELURUH ISI MIGRASI INI BUTIR SEMENTARA, sama seperti migrasi 169. Ia
-- ditulis untuk MENGUJI MESINNYA, bukan untuk mengajar anak. Sebelum
-- aplikasinya dipublikasikan ke murid, isinya harus diganti butir yang ditulis
-- dan diverifikasi sungguhan — atau topiknya dinonaktifkan lagi.
--
-- Semuanya bisa dicabut dengan tiga perintah. Tidak ada penanda sumber
-- tersendiri: `question_bank_items_sumber_check` hanya mengizinkan 'manual'
-- dan 'ai_generated_verified', dan menambah nilai ketiga demi kenyamanan
-- membersihkan berarti melonggarkan batasan yang menjaga hal lain. Yang
-- dipakai sebagai pegangan adalah topik dan levelnya:
--
--   delete from question_bank_items
--    where topik_id in ('D-04','D-05','D-06','D-07','D-09','D-10','D-11',
--                       'D-12','D-13','D-14','D-15','D-16','D-17','D-18','D-19');
--   delete from question_bank_items
--    where topik_id in ('D-01','D-02','D-03','D-08') and bloom_level >= 4;
--   update topik set aktif = false where id not in ('D-01','D-02','D-03','D-08');
--
-- KENAPA SELURUH TOPIK. Sampai hari ini hanya empat topik yang punya butir,
-- dan hanya level C1–C3. Akibatnya dua bagian sistem tidak pernah sekali pun
-- dijalankan: rantai prasyarat yang panjangnya lebih dari tiga, dan paket
-- Bloom C4–C6 yang label serta perhitungannya sudah lama siap tapi tidak
-- pernah punya butir untuk dilahirkan. `semai_paket_topik` sendiri tidak perlu
-- diubah sama sekali — ia memang melahirkan satu paket untuk TIAP level Bloom
-- yang ada butirnya, jadi yang selama ini hilang bukan mesinnya melainkan
-- isinya.
--
-- ENAM LEVEL, bukan tiga. Dokumen fondasi Bagian 3.2 meminta enam paket Bloom
-- per topik. Yang dibangun sampai sekarang tiga, dan itu keputusan pilot yang
-- sah — tapi keputusan itu tidak pernah bisa ditinjau ulang selama C4–C6 tidak
-- punya satu butir pun untuk dilihat bentuknya.
--
-- BENTUK SOALNYA IKUT DILENGKAPI. `matching`, `ordering`, dan `fill_blank`
-- sudah dirender `InputSoal` dan sudah dinilai `nilai_jawaban()`, tapi tidak
-- satu butir pun di bank memakainya — tiga widget jawaban yang tidak pernah
-- sekali pun dilewati murid. Migrasi ini menaruhnya di paket ujian, tempat
-- dokumen fondasi Bagian 3.7 memang meminta bentuk soal dicampur. Bersama
-- `mcq_multi` (PGK MCMA) dan `statement_grid` (PGK Kategori) yang diminta PRD
-- Bagian 5, delapan bentuk soal yang bisa dinilai mesin kini semuanya terpakai.
--
-- JAWABANNYA DIHITUNG, BUKAN DIKETIK, dan diperiksa mesin sebelum sampai ke
-- sini — aturan yang sama dengan migrasi 169, ditambah satu pemeriksaan yang
-- dulu tidak ada: TIDAK ADA DISTRAKTOR YANG BERNILAI SAMA DENGAN KUNCINYA.
-- Pemeriksaan 169 membandingkan teks opsi, bukan nilainya, dan sebelas butir
-- penjumlahan pecahan lolos dengan distraktor yang secara matematika adalah
-- jawaban benar (8/16 untuk kunci 1/2). Di sini nilainya yang dibandingkan,
-- dan 22 tabrakan tertangkap lalu diperbaiki sebelum berkas ini ditulis.
--
-- Jalankan SESUDAH 170.
-- ============================================================

-- Penyisip tunggal, supaya sembilan belas blok di bawah tidak mengulang badan
-- insert yang sama sembilan belas kali. Sementara: dibuang di ujung berkas.
create or replace function sisip_butir_dummy(p_butir jsonb, p_penulis uuid)
returns void
language plpgsql
as $fn$
declare
  v_id uuid;
begin
  -- Idempoten per BUTIR, bukan per migrasi: menjalankan berkas ini dua kali
  -- tidak melahirkan salinan, dan menambah butir baru di kemudian hari tidak
  -- terhalang butir lama yang sudah masuk.
  if exists (
    select 1 from question_bank_items
    where topik_id = p_butir ->> 'topik' and prompt = p_butir ->> 'prompt'
  ) then
    return;
  end if;

  insert into question_bank_items (
    created_by, type, prompt, options, correct_answer, weight,
    bloom_level, status_verifikasi, penjelasan_per_opsi,
    elemen_proses, sumber_pembuatan, peruntukan, topik_id
  ) values (
    p_penulis,
    p_butir ->> 'type',
    p_butir ->> 'prompt',
    case when jsonb_typeof(p_butir -> 'opsi') = 'object' then p_butir -> 'opsi' else null end,
    p_butir -> 'kunci',
    1,
    (p_butir ->> 'bloom')::smallint,
    'aktif',
    case when jsonb_typeof(p_butir -> 'why') = 'array' then (
      select jsonb_object_agg((i - 1)::text, w)
      from jsonb_array_elements_text(p_butir -> 'why') with ordinality as t(w, i)
    ) else null end,
    array['penalaran']::text[],
    'ai_generated_verified',
    p_butir ->> 'peruntukan',
    p_butir ->> 'topik'
  )
  returning id into v_id;

  -- Butir probe TIDAK jadi anggota paket (trigger migrasi 164 menolaknya),
  -- jadi ia hanya masuk kolam probenya sendiri.
  if (p_butir ->> 'peruntukan') = 'probe' then
    insert into item_probe (topik_id, question_bank_item_id)
    values (p_butir ->> 'topik', v_id)
    on conflict do nothing;
  end if;
end;
$fn$;

